// ── Grouped by tribe ─────────────────────────────────────────────
const flashcardsByTribe = wordFlashcardsSeed.reduce(function(groups, card) {
  const tribe = card.tribe || "General Uganda";
  if (!groups[tribe]) groups[tribe] = [];
  groups[tribe].push(card);
  return groups;
}, {});

// ── Grouped by category ──────────────────────────────────────────
const flashcardsByCategory = wordFlashcardsSeed.reduce(function(groups, card) {
  const category = card.category || "Uncategorized";
  if (!groups[category]) groups[category] = [];
  groups[category].push(card);
  return groups;
}, {});

// ── Grouped by language ──────────────────────────────────────────
const flashcardsByLanguage = wordFlashcardsSeed.reduce(function(groups, card) {
  const lang = card.language || "Unknown";
  if (!groups[lang]) groups[lang] = [];
  groups[lang].push(card);
  return groups;
}, {});

// ── Quick lookup by ID ───────────────────────────────────────────
const flashcardsById = wordFlashcardsSeed.reduce(function(map, card) {
  map[card.id] = card;
  return map;
}, {});

// ── Quick lookup by slug ─────────────────────────────────────────
const flashcardsBySlug = wordFlashcardsSeed.reduce(function(map, card) {
  map[card.slug] = card;
  return map;
}, {});

// ── Summary stats ────────────────────────────────────────────────
const seedSummary = {
  totalCards: wordFlashcardsSeed.length,
  tribes: Object.keys(flashcardsByTribe).sort(),
  categories: Object.keys(flashcardsByCategory).sort(),
  languages: Object.keys(flashcardsByLanguage).sort(),
  cardsByTribeCount: Object.keys(flashcardsByTribe).reduce(function(acc, t) {
    acc[t] = flashcardsByTribe[t].length; return acc;
  }, {}),
  cardsByCategoryCount: Object.keys(flashcardsByCategory).reduce(function(acc, c) {
    acc[c] = flashcardsByCategory[c].length; return acc;
  }, {}),
  audioStatus: {
    withAudio: wordFlashcardsSeed.filter(function(c) { return c.audio.currentAudioUrl !== null; }).length,
    pendingAudio: wordFlashcardsSeed.filter(function(c) { return c.audio.currentAudioUrl === null; }).length,
    allReplaceable: wordFlashcardsSeed.every(function(c) { return c.audio.isReplaceable === true; })
  }
};

module.exports = {
  wordFlashcardsSeed,
  flashcardsByTribe,
  flashcardsByCategory,
  flashcardsByLanguage,
  flashcardsById,
  flashcardsBySlug,
  seedSummary
};
